'use client';

import * as React from 'react';
import { useEffect, useEffectEvent, useMemo } from 'react';

import { RowData, useTable } from '@tanstack/react-table';
import { ChevronDown, ChevronRight } from 'lucide-react';

import { DataTableContent } from '@/components/ui-fragments/data-table/data-table-content';
import {
  type ColumnDef,
  dataTableFeatures,
  type InitialTableState,
  type ReactTable,
  type Row,
  type TDataTableOptions,
} from '@/components/ui-fragments/data-table/data-table-features';
import { DataTablePagination } from '@/components/ui-fragments/data-table/data-table-pagination';
import {
  DataTableToolbar,
  type TDataTableToolbarProps,
} from '@/components/ui-fragments/data-table/data-table-toolbar';
import { Button } from '@/registry/default/ui/button';

export type TDataTableProps<TData extends RowData> = {
  columns: ColumnDef<TData>[];
  /** The rows. `undefined` reads as no row, while the data loads. */
  data: TData[] | undefined;
  /** The state the table starts from. Read once, on the first render. */
  initialState?: InitialTableState;
  emptyState?: React.ReactNode;
  renderExpandedRow?: (row: Row<TData>) => React.ReactNode;
  getRowCanExpand?: (row: Row<TData>) => boolean;
  /** The id of a row. Without it, the id is the row index. */
  getRowId?: (row: TData, index: number) => string;
  autoResetPageIndex?: boolean;
  autoResetExpanded?: boolean;
  /** Whether the pager is drawn under the table. Default `true`. */
  displayPagination?: boolean;
  /** Hides the toolbar whatever its other props say. Default `false`. */
  hideToolbar?: boolean;
  /**
   * Hands the table to the caller once, on mount, to drive it from outside
   * the toolbar. Its methods read the live state; to re-render on a change,
   * wrap the reader in `table.Subscribe`.
   */
  onTableReady?: (table: ReactTable<TData>) => void;
  /**
   * Any other TanStack option, passed to `useTable` as is: turn row selection
   * off, turn cell selection on, control a state slice, listen to a change.
   */
  tableOptions?: TDataTableOptions<TData>;
} & Pick<
  TDataTableToolbarProps<TData>,
  | 'searchConfig'
  | 'filtersConfig'
  | 'displayViewOptions'
  | 'toolbarLeft'
  | 'toolbarRight'
>;

export function DataTable<TData extends RowData>({
  columns,
  data,
  initialState,
  emptyState,
  renderExpandedRow,
  getRowCanExpand,
  getRowId,
  autoResetPageIndex,
  autoResetExpanded,
  displayPagination = true,
  hideToolbar = false,
  onTableReady,
  tableOptions,
  searchConfig,
  filtersConfig,
  displayViewOptions,
  toolbarLeft,
  toolbarRight,
}: TDataTableProps<TData>) {
  const rows = useMemo(() => data ?? [], [data]);

  const table = useTable({
    enableRowSelection: true,
    enableCellSelection: false,
    columnResizeMode: 'onChange',
    ...tableOptions,
    features: dataTableFeatures,
    data: rows,
    columns,
    initialState: {
      ...initialState,
      columnPinning: {
        start: initialState?.columnPinning?.start ?? [],
        end: initialState?.columnPinning?.end ?? [],
      },
      pagination: initialState?.pagination && {
        pageIndex: 0,
        ...initialState.pagination,
      },
    },
    autoResetPageIndex,
    autoResetExpanded,
    getRowCanExpand,
    getRowId,
  });

  const handOverTable = useEffectEvent(() => onTableReady?.(table));

  useEffect(() => {
    handOverTable();
  }, []);

  return (
    <div className="w-full space-y-4">
      {!hideToolbar && (
        <DataTableToolbar
          table={table}
          searchConfig={searchConfig}
          filtersConfig={filtersConfig}
          displayViewOptions={displayViewOptions}
          toolbarLeft={toolbarLeft}
          toolbarRight={toolbarRight}
        />
      )}
      <DataTableContent
        table={table}
        renderExpandedRow={renderExpandedRow}
        emptyState={emptyState}
      />
      {displayPagination && <DataTablePagination table={table} />}
    </div>
  );
}

export function createExpandColumn<TData extends RowData>(): ColumnDef<TData> {
  return {
    id: 'expand',
    header: () => null,
    cell: ({ row }) =>
      row.getCanExpand() ? (
        <Button
          variant="ghost"
          size="icon-sm"
          onClick={() => row.toggleExpanded()}
          aria-label={row.getIsExpanded() ? 'Collapse row' : 'Expand row'}
          aria-expanded={row.getIsExpanded()}
        >
          {row.getIsExpanded() ? (
            <ChevronDown />
          ) : (
            <ChevronRight className="rtl:rotate-180" />
          )}
        </Button>
      ) : null,
    size: 47,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
  };
}

import type { CSSProperties } from 'react';

import type { RowData } from '@tanstack/react-table';

import type { Column } from '@/components/ui-fragments/data-table/data-table-features';

const COLUMN_RULE = '1px solid var(--border)';

export const getCommonPinningStyles = <TData extends RowData>(
  column: Column<TData>,
  isLastRow?: boolean,
  hasStartPinnedColumns?: boolean
): CSSProperties => {
  const isPinned = column.getIsPinned();
  const isLastStartPinnedColumn =
    isPinned === 'start' && column.getIsLastColumn('start');
  const isFirstCenterColumnAfterStartPins =
    hasStartPinnedColumns && !isPinned && column.getIsFirstColumn('center');
  // A sticky inset is the sum of the sizes of the pins before it, so a pin
  // that sets another pin's inset keeps its exact size. A sole pin grows to
  // its content, like any other cell.
  const setsAnotherPinInset =
    (isPinned === 'start' && !isLastStartPinnedColumn) ||
    (isPinned === 'end' && !column.getIsFirstColumn('end'));

  return {
    borderInlineEnd:
      isLastStartPinnedColumn && !column.getIsLastColumn()
        ? COLUMN_RULE
        : undefined,
    borderInlineStart: column.getIsFirstColumn()
      ? undefined
      : isFirstCenterColumnAfterStartPins
        ? 'none'
        : COLUMN_RULE,
    borderBlockEnd: !isLastRow ? COLUMN_RULE : undefined,
    insetInlineStart:
      isPinned === 'start' ? `${column.getStart('start')}px` : undefined,
    insetInlineEnd:
      isPinned === 'end' ? `${column.getAfter('end')}px` : undefined,
    position: isPinned ? 'sticky' : 'relative',
    width: column.getSize(),
    ...(setsAnotherPinInset && {
      boxSizing: 'border-box',
      minWidth: column.getSize(),
      maxWidth: column.getSize(),
    }),
    zIndex: isPinned ? 1 : 0,
  };
};

'use client';

import * as React from 'react';

import { RowData } from '@tanstack/react-table';

import type {
  ReactTable,
  Row,
} from '@/components/ui-fragments/data-table/data-table-features';
import { getCommonPinningStyles } from '@/components/ui-fragments/data-table/data-table-pinning';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/default/ui/table';

export type TDataTableContentProps<TData extends RowData> = {
  table: ReactTable<TData>;
  /** Drawn under an expanded row, across all its cells. */
  renderExpandedRow?: (row: Row<TData>) => React.ReactNode;
  /**
   * Drawn instead of the table when the data has no row. A filter that leaves
   * no row shows "No results." in the table instead.
   */
  emptyState?: React.ReactNode;
};

function DataTableHeader<TData extends RowData>({
  table,
  hasStartPinnedColumns,
  withResizeHandles,
}: {
  table: ReactTable<TData>;
  hasStartPinnedColumns: boolean;
  withResizeHandles: boolean;
}) {
  return (
    <TableHeader>
      {table.getHeaderGroups().map((headerGroup) => (
        <TableRow key={headerGroup.id}>
          {headerGroup.headers.map((header) => (
            <TableHead
              key={header.id}
              colSpan={header.colSpan}
              className="relative whitespace-nowrap"
              style={getCommonPinningStyles(
                header.column,
                false,
                hasStartPinnedColumns
              )}
            >
              {header.isPlaceholder ? null : (
                <table.FlexRender header={header} />
              )}
              {withResizeHandles && header.column.getCanResize() && (
                <div
                  onDoubleClick={() => header.column.resetSize()}
                  onMouseDown={header.getResizeHandler()}
                  onTouchStart={header.getResizeHandler()}
                  role="separator"
                  tabIndex={-1}
                  aria-label="Resize column"
                  aria-hidden="true"
                  aria-orientation="vertical"
                  data-resizing={header.column.getIsResizing()}
                  className="absolute inset-y-0 end-0 w-[5px] cursor-col-resize touch-none select-none bg-transparent opacity-0 transition-opacity duration-200 hover:opacity-50 data-[resizing=true]:bg-primary data-[resizing=true]:opacity-100"
                />
              )}
            </TableHead>
          ))}
        </TableRow>
      ))}
    </TableHeader>
  );
}

export function DataTableContent<TData extends RowData>({
  table,
  renderExpandedRow,
  emptyState,
}: TDataTableContentProps<TData>) {
  const rows = table.getRowModel().rows;
  const hasData = table.getCoreRowModel().rows.length > 0;
  const hasStartPinnedColumns = table.state.columnPinning.start.length > 0;
  const selectsCells = table.options.enableCellSelection !== false;

  if (!hasData) {
    if (emptyState) {
      return emptyState;
    }

    return (
      <div className="overflow-hidden rounded-md border border-border [&_[data-slot=table-container]]:rounded-none [&_[data-slot=table-container]]:border-0">
        <Table className="border-separate border-spacing-0">
          <DataTableHeader
            table={table}
            hasStartPinnedColumns={hasStartPinnedColumns}
            withResizeHandles={false}
          />
        </Table>
        <div className="flex h-24 items-center justify-center bg-card text-center">
          No results.
        </div>
      </div>
    );
  }

  return (
    <Table className="border-separate border-spacing-0">
      <DataTableHeader
        table={table}
        hasStartPinnedColumns={hasStartPinnedColumns}
        withResizeHandles
      />
      <TableBody>
        {rows.length === 0 && (
          <TableRow>
            <TableCell
              colSpan={table.getVisibleLeafColumns().length}
              className="h-24 text-center"
            >
              No results.
            </TableCell>
          </TableRow>
        )}
        {rows.map((row, rowIndex) => {
          const isLastRow = rowIndex === rows.length - 1;
          const showsExpandedRow =
            row.getIsExpanded() && renderExpandedRow !== undefined;

          return (
            <React.Fragment key={row.id}>
              <TableRow data-state={row.getIsSelected() && 'selected'}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    {...(selectsCells &&
                      cell.getCanSelect() && {
                        'data-selected': cell.getIsSelected(),
                        onMouseDown: cell.getSelectionStartHandler(),
                        onMouseEnter: cell.getSelectionExtendHandler(),
                      })}
                    className={
                      selectsCells
                        ? 'select-none data-[selected=true]:bg-accent'
                        : undefined
                    }
                    style={getCommonPinningStyles(
                      cell.column,
                      isLastRow && !showsExpandedRow,
                      hasStartPinnedColumns
                    )}
                  >
                    <table.FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
              {showsExpandedRow && (
                <TableRow>
                  <TableCell
                    colSpan={row.getVisibleCells().length}
                    className="p-0"
                    style={{
                      borderBlockEnd: isLastRow
                        ? undefined
                        : '1px solid var(--border)',
                    }}
                  >
                    {renderExpandedRow(row)}
                  </TableCell>
                </TableRow>
              )}
            </React.Fragment>
          );
        })}
      </TableBody>
    </Table>
  );
}

'use client';

import * as React from 'react';

import { RowData } from '@tanstack/react-table';
import { X } from 'lucide-react';

import {
  DataTableFacetedFilter,
  type TFacetedFilterOption,
} from '@/components/ui-fragments/data-table/data-table-faceted-filter';
import type { ReactTable } from '@/components/ui-fragments/data-table/data-table-features';
import { DataTableViewOptions } from '@/components/ui-fragments/data-table/data-table-view-options';
import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import { Input } from '@/registry/default/ui/input';

export type TDataTableSearchConfig = {
  placeholder: string;
  columnKey: string;
  size?: 'sm' | 'md' | 'lg';
};

export type TDataTableFilterConfig = {
  title: string;
  column: string;
  options: TFacetedFilterOption[];
  /** What the trigger says once something is picked. Default `badges`. */
  selectionDisplay?: 'badges' | 'count';
};

export type TDataTableToolbarProps<TData extends RowData> = {
  table: ReactTable<TData>;
  searchConfig?: TDataTableSearchConfig[];
  filtersConfig?: TDataTableFilterConfig[];
  toolbarLeft?: React.ReactNode;
  toolbarRight?: React.ReactNode;
  /** Whether the "All columns" control is shown. Default `true`. */
  displayViewOptions?: boolean;
};

export function DataTableToolbar<TData extends RowData>({
  table,
  searchConfig,
  filtersConfig,
  toolbarLeft,
  toolbarRight,
  displayViewOptions = true,
}: TDataTableToolbarProps<TData>) {
  const isFiltered = table.state.columnFilters.length > 0;
  const isEmpty =
    !displayViewOptions &&
    !searchConfig &&
    !filtersConfig &&
    !toolbarLeft &&
    !toolbarRight &&
    !isFiltered;

  if (isEmpty) {
    return null;
  }

  return (
    <div className="flex flex-wrap items-center justify-between gap-2">
      <div
        className="flex flex-wrap items-center gap-2 *:flex-wrap"
        data-testid="datatable-toolbar-left"
      >
        {toolbarLeft}
        {searchConfig?.map((search, index) => (
          <Input
            key={search.columnKey}
            placeholder={search.placeholder}
            data-testid={`datatable-search-${index}`}
            value={
              (table.getColumn(search.columnKey)?.getFilterValue() as string) ??
              ''
            }
            onChange={(event) =>
              table
                .getColumn(search.columnKey)
                ?.setFilterValue(event.target.value)
            }
            className={cn({
              'w-28': search.size === 'sm',
              'w-40 lg:w-52': search.size === 'md' || !search.size,
              'w-56': search.size === 'lg',
            })}
          />
        ))}
        {filtersConfig?.map((filter) => {
          const column = table.getColumn(filter.column);

          return column ? (
            <DataTableFacetedFilter
              key={filter.column}
              column={column}
              title={filter.title}
              options={filter.options}
              selectionDisplay={filter.selectionDisplay}
            />
          ) : null;
        })}

        {isFiltered && (
          <Button
            variant="ghost"
            onClick={() => table.setColumnFilters([])}
            size="md"
            className="ms-3 gap-2 px-2 lg:px-3"
          >
            Reset
            <X className="size-4" />
          </Button>
        )}
      </div>

      <div
        className="flex flex-wrap items-center gap-2 *:flex-wrap sm:ms-auto sm:justify-end"
        data-testid="datatable-toolbar-right"
      >
        {toolbarRight}
        {displayViewOptions && <DataTableViewOptions table={table} />}
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';

import { RowData } from '@tanstack/react-table';
import { Check, CirclePlus } from 'lucide-react';

import type { Column } from '@/components/ui-fragments/data-table/data-table-features';
import { cn } from '@/lib/utils';
import { Badge, type TBadgeProps } from '@/registry/default/ui/badge';
import { Button } from '@/registry/default/ui/button';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '@/registry/default/ui/command';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/default/ui/popover';
import { Separator } from '@/registry/default/ui/separator';

export type TFacetedFilterOption = {
  label: string;
  value: string;
  icon?: React.ComponentType<{ className?: string }>;
  variant?: TBadgeProps['variant'];
};

export type TDataTableFacetedFilterProps<TData extends RowData, TValue> = {
  column?: Column<TData, TValue>;
  title?: string;
  options: TFacetedFilterOption[];
  /**
   * What the trigger shows once something is picked: `badges` names up to two
   * picks, then a count; `count` always shows a count (for long labels).
   */
  selectionDisplay?: 'badges' | 'count';
};

export function DataTableFacetedFilter<TData extends RowData, TValue>({
  column,
  title,
  options,
  selectionDisplay = 'badges',
}: TDataTableFacetedFilterProps<TData, TValue>) {
  const facets = column?.getFacetedUniqueValues();
  const selectedValues = new Set(column?.getFilterValue() as string[]);

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outlineDashed"
          className="gap-2"
          data-testid={`datatable-filter-${title?.toLowerCase()}`}
        >
          <CirclePlus className="size-4" />

          <span>{title}</span>

          {selectedValues.size > 0 && (
            <>
              <Separator orientation="vertical" className="mx-2 h-4" />
              <div className="flex gap-x-1">
                {selectionDisplay === 'count' || selectedValues.size > 2 ? (
                  <Badge variant="secondary">
                    {selectedValues.size} selected
                  </Badge>
                ) : (
                  options.flatMap((option) =>
                    selectedValues.has(option.value)
                      ? [
                          <Badge
                            variant={option.variant ?? 'primary'}
                            key={option.value}
                          >
                            {option.label}
                          </Badge>,
                        ]
                      : []
                  )
                )}
              </div>
            </>
          )}
        </Button>
      </PopoverTrigger>

      <PopoverContent
        className="w-auto min-w-[200px] max-w-xs p-0"
        align="start"
      >
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>No results found.</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selectedValues.has(option.value);

                return (
                  <CommandItem
                    key={option.value}
                    data-testid={`datatable-filters-${option.label.toLowerCase()}`}
                    onSelect={() => {
                      if (isSelected) {
                        selectedValues.delete(option.value);
                      } else {
                        selectedValues.add(option.value);
                      }
                      const filterValues = Array.from(selectedValues);
                      column?.setFilterValue(
                        filterValues.length ? filterValues : undefined
                      );
                    }}
                  >
                    <div
                      className={cn(
                        'me-2 flex size-4 shrink-0 items-center justify-center rounded-sm border border-primary',
                        isSelected
                          ? "bg-primary text-primary-foreground! [&_svg:not([class*='text-'])]:text-primary-foreground"
                          : 'opacity-50 [&_svg]:invisible'
                      )}
                    >
                      {isSelected && <Check className="size-4" />}
                    </div>
                    {option.icon && (
                      <option.icon className="me-2 size-4 shrink-0 text-muted-foreground" />
                    )}
                    <span className="min-w-0 truncate">{option.label}</span>
                    {facets?.get(option.value) && (
                      <span className="ms-auto flex size-4 shrink-0 items-center justify-center font-mono text-xs">
                        {facets.get(option.value)}
                      </span>
                    )}
                  </CommandItem>
                );
              })}
            </CommandGroup>
            {selectedValues.size > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={() => column?.setFilterValue(undefined)}
                    className="justify-center text-center"
                  >
                    Clear filters
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

'use client';

import { RowData } from '@tanstack/react-table';
import { Settings2 } from 'lucide-react';

import type { ReactTable } from '@/components/ui-fragments/data-table/data-table-features';
import { Button } from '@/registry/default/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/default/ui/dropdown-menu';

export type TDataTableViewOptionsProps<TData extends RowData> = {
  table: ReactTable<TData>;
};

export function DataTableViewOptions<TData extends RowData>({
  table,
}: TDataTableViewOptionsProps<TData>) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="md" className="ms-auto flex gap-2">
          <Settings2 className="size-4" />
          All columns
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-[150px]">
        <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {table.getAllColumns().flatMap((column) =>
          typeof column.accessorFn !== 'undefined' && column.getCanHide()
            ? [
                <DropdownMenuCheckboxItem
                  key={column.id}
                  className={column.columnDef.meta?.label ? '' : 'capitalize'}
                  checked={column.getIsVisible()}
                  onCheckedChange={(value) => column.toggleVisibility(!!value)}
                >
                  {column.columnDef.meta?.label ?? column.id}
                </DropdownMenuCheckboxItem>,
              ]
            : []
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import * as React from 'react';

import { RowData } from '@tanstack/react-table';
import { ArrowDown, ArrowUp, ChevronDown, EyeOff } from 'lucide-react';

import type { Column } from '@/components/ui-fragments/data-table/data-table-features';
import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/default/ui/dropdown-menu';

export type TDataTableColumnHeaderProps<
  TData extends RowData,
  TValue,
> = React.HTMLAttributes<HTMLDivElement> & {
  column: Column<TData, TValue>;
  title: string;
};

export function DataTableColumnHeader<TData extends RowData, TValue>({
  column,
  title,
  className,
}: TDataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return <div className={cn(className)}>{title}</div>;
  }

  return (
    <div className={cn('flex items-center gap-x-2', className)}>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="md"
            className="-ms-1.5 gap-2 px-1.5 data-[state=open]:bg-accent"
          >
            <span>{title}</span>
            {column.getIsSorted() === 'desc' ? (
              <ArrowDown className="size-4" />
            ) : column.getIsSorted() === 'asc' ? (
              <ArrowUp className="size-4" />
            ) : (
              <ChevronDown className="size-4" />
            )}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          <DropdownMenuItem onClick={() => column.toggleSorting(false)}>
            <ArrowUp className="me-2 size-3.5 text-muted-foreground/70" />
            Asc
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => column.toggleSorting(true)}>
            <ArrowDown className="me-2 size-3.5 text-muted-foreground/70" />
            Desc
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={() => column.toggleVisibility(false)}>
            <EyeOff className="me-2 size-3.5 text-muted-foreground/70" />
            Hide
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

'use client';

import { RowData } from '@tanstack/react-table';
import { ChevronLeft, ChevronRight } from 'lucide-react';

import type { ReactTable } from '@/components/ui-fragments/data-table/data-table-features';
import { Button } from '@/registry/default/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/default/ui/select';

const PAGE_SIZES = [2, 5, 10, 15, 20, 30, 40, 50];

export type TDataTablePageSizeSelectProps = {
  value: number;
  onValueChange: (value: number) => void;
  disabled?: boolean;
};

/** The "Rows per page" select, for a custom pager. */
export function DataTablePageSizeSelect({
  value,
  onValueChange,
  disabled,
}: TDataTablePageSizeSelectProps) {
  return (
    <div className="me-2 flex items-center gap-x-2">
      <p className="text-sm font-medium">Rows per page</p>
      <Select
        disabled={disabled}
        value={`${value}`}
        onValueChange={(size) => onValueChange(Number(size))}
      >
        <SelectTrigger
          className="w-[70px]"
          aria-label="Rows per page"
          data-testid="datatable-page-size-selector"
        >
          <SelectValue placeholder={value} />
        </SelectTrigger>
        <SelectContent side="top">
          {PAGE_SIZES.map((size) => (
            <SelectItem
              key={size}
              value={`${size}`}
              data-testid={`datatable-page-size-${size}`}
            >
              {size}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

export type TDataTablePaginationProps<TData extends RowData> = {
  table: ReactTable<TData>;
};

export function DataTablePagination<TData extends RowData>({
  table,
}: TDataTablePaginationProps<TData>) {
  const { pageIndex, pageSize } = table.state.pagination;

  return (
    <div
      className="flex flex-wrap items-center justify-end gap-y-2 px-2"
      data-testid="datatable-pagination"
    >
      <div className="flex flex-wrap items-center justify-end gap-x-6 gap-y-2 lg:gap-x-8">
        <DataTablePageSizeSelect
          value={pageSize}
          onValueChange={(size) => table.setPageSize(size)}
        />

        <div className="me-2 flex items-center justify-center text-sm font-medium">
          Page {pageIndex + 1} of {table.getPageCount()}
        </div>

        <div className="flex items-center gap-x-2">
          <Button
            variant="outline"
            className="gap-2"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            type="button"
            aria-label="Go to previous page"
            data-testid="datatable-previous-page"
          >
            <ChevronLeft className="size-4 rtl:rotate-180" />
            Previous
          </Button>
          <Button
            variant="outline"
            className="gap-2"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            type="button"
            aria-label="Go to next page"
            data-testid="datatable-next-page"
          >
            Next
            <ChevronRight className="size-4 rtl:rotate-180" />
          </Button>
        </div>
      </div>
    </div>
  );
}

import * as React from 'react';

import { cn } from '@/lib/utils';
import { Skeleton } from '@/registry/default/ui/skeleton';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/default/ui/table';

export type TDataTableSkeletonProps = React.HTMLAttributes<HTMLDivElement> & {
  /** The number of columns in the table. */
  columnCount: number;
  /**
   * The total number of rows in the table. With `withColumnsOptions` it
   * includes the header row; without, it counts the body rows only.
   * @default 10
   */
  rowCount?: number;
  /** The number of search inputs in the toolbar. @default 0 */
  searchableColumnCount?: number;
  /** The number of faceted filters in the toolbar. @default 0 */
  filterableColumnCount?: number;
  /** Whether the toolbar shows the view options control. @default true */
  showViewOptions?: boolean;
  /**
   * The width of each cell, one CSS width per column.
   * @default ['auto']
   */
  cellWidths?: string[];
  /** Whether the header row is drawn. @default true */
  withColumnsOptions?: boolean;
  /** Whether the pagination bar is drawn. @default true */
  withPagination?: boolean;
  /** Whether the cells keep their width instead of shrinking. @default false */
  shrinkZero?: boolean;
};

export function DataTableSkeleton({
  columnCount,
  rowCount = 10,
  searchableColumnCount = 0,
  filterableColumnCount = 0,
  showViewOptions = true,
  cellWidths = ['auto'],
  withColumnsOptions = true,
  withPagination = true,
  shrinkZero = false,
  className,
  ...props
}: TDataTableSkeletonProps) {
  const bodyRowCount = withColumnsOptions
    ? Math.max(0, rowCount - 1)
    : rowCount;
  const cellStyle = (index: number): React.CSSProperties => ({
    width: cellWidths[index],
    minWidth: shrinkZero ? cellWidths[index] : 'auto',
  });

  return (
    <div
      className={cn('w-full space-y-2.5 overflow-auto', className)}
      {...props}
    >
      <div className="flex w-full items-center justify-between gap-x-2 overflow-auto p-1">
        <div className="flex flex-1 items-center gap-x-2">
          {Array.from({ length: searchableColumnCount }).map((_, i) => (
            <Skeleton key={i} className="h-7 w-40 lg:w-60" />
          ))}
          {Array.from({ length: filterableColumnCount }).map((_, i) => (
            <Skeleton key={i} className="h-7 w-[4.5rem] border-dashed" />
          ))}
        </div>
        {showViewOptions && (
          <Skeleton className="ms-auto hidden h-7 w-[4.5rem] lg:flex" />
        )}
      </div>
      <Table>
        {withColumnsOptions && (
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              {Array.from({ length: columnCount }).map((_, j) => (
                <TableHead key={j} style={cellStyle(j)}>
                  <Skeleton className="h-6 w-full" />
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
        )}
        <TableBody>
          {Array.from({ length: bodyRowCount }).map((_, i) => (
            <TableRow key={i} className="hover:bg-transparent">
              {Array.from({ length: columnCount }).map((_, j) => (
                <TableCell key={j} style={cellStyle(j)}>
                  <Skeleton className="h-6 w-full" />
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
      {withPagination && (
        <div className="flex w-full items-center justify-between gap-4 overflow-auto p-1 sm:gap-8">
          <Skeleton className="h-7 w-40 shrink-0" />
          <div className="flex items-center gap-4 sm:gap-6 lg:gap-8">
            <div className="flex items-center gap-x-2">
              <Skeleton className="h-7 w-24" />
              <Skeleton className="h-7 w-[4.5rem]" />
            </div>
            <Skeleton className="h-7 w-20" />
            <div className="flex items-center gap-x-2">
              <Skeleton className="h-7 w-24" />
              <Skeleton className="h-7 w-20" />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

